INSERT INTO "Characters" ("_row", "Id", "Name", "AOFile", "ACTFile", "BaseMaxLife", "BaseMaxMana", "WeaponSpeed", "MinDamage", "MaxDamage", "MaxAttackDistance", "Icon", "IntegerId", "BaseStrength", "BaseDexterity", "BaseIntelligence", "StartingMeleeSkill", "Description", "StartSkillGem", "__col18", "__col19", "__col20", "CharacterSize", "IntroSoundFile", "StartWeapons", "Gender", "TraitDescription", "StartSupportGem", "__col27", "__col28", "StartingWeaponBase", "__col30", "Mods", "PassiveTreeImage", "__col33", "__col34", "TencentVideo", "AttrsAsId", "LoginScreen", "PlayerCritter", "PlayerEffect", "AfterImage", "Mirage", "CloneImmobile", "ReplicateClone", "LightningClone", "__col45", "__col46", "SkillTreeBackground", "Clone", "Double", "MirageWarrior", "DoubleTwo", "DarkExile", "Attr", "AttrLowercase", "Script", "GhostArmMtx", "__col57", "__col58", "__col59", "__col60", "__col61", "LightningCloneBreach", "__col63") VALUES
(0, 'Metadata/Characters/Str/Str', 'Marauder', 'Metadata/Characters/Str/Str.ao', 'Metadata/Characters/Str/Str.act', 38, 34, 833, 2, 8, 8, '', 1, 32, 14, 14, '[4474]', 'Do you think you are savage enough to face the land of the damned, Marauder?' || char(13) || '
 ' || char(13) || '
We offered you truth yet still you clasped your superstitious lies. We offered you service, yet you wasted your strength in defiance.' || char(13) || '
 ' || char(13) || '
Wraeclast offers you something else: an education in true savagery.', 101, 0, 6, 1, 2, 'Audio/Dialogue/NPC/DominusGlyph/Dom_Intro_Marauder.ogg', '[556]', 'M', 'Traits: Strength, Melee', 340, 242, 340, 719, 1, '[1231]', 'Art/2DArt/BaseClassIllustrations/Str.dds', -1736, -1350, 'http://down.qq.com/poe/videos/class/ClassStr.bk2', 'Str', 'Metadata/Characters/Str/StrLoginSceneFallOfOriath.ao', 'Metadata/Critters/PlayerCritters/StrCritter', 'Metadata/Effects/PlayerEffects/StrEffect', 'Metadata/Effects/Spells/maneuver_mechanics/AfterImage/StrAfterImage', 3982, 3961, 3989, 6706, 350, -574, 'Art/2DArt/UIImages/InGame/Classes/Str/PassiveSkillScreenStartNodeBackground', 3954, 3607, 8411, 3614, 2792, 'Str', 'str', 'str_back', 521, 100, 3968, 3975, 1, 100, 10475, 3629),
(1, 'Metadata/Characters/Int/Int', 'Witch', 'Metadata/Characters/Int/Int.ao', 'Metadata/Characters/Int/Int.act', 38, 34, 833, 2, 5, 8, '', 3, 14, 14, 32, '[4474]', 'Why do the keen of mind seek to satiate their curiosity in darkness and depravity?' || char(13) || '
 ' || char(13) || '
Innocence is our Father, Oriath is our Mother. When a daughter strays from the light, she makes herself an orphan.' || char(13) || '
 ' || char(13) || '
Learn well the lessons that Wraeclast will teach you, Witch. It is your only hope of finding your way home.', 0, 0, 6, 1, 2, 'Audio/Dialogue/NPC/DominusGlyph/Dom_Intro_Witch.ogg', '[384]', 'F', 'Traits: Intelligence, Spells', 342, 286, 342, 384, 2, '[4536]', 'Art/2DArt/BaseClassIllustrations/Int.dds', -1532, -669, 'http://down.qq.com/poe/videos/class/ClassInt.bk2', 'Int', 'Metadata/Characters/Int/IntLoginSceneFallOfOriath.ao', 'Metadata/Critters/PlayerCritters/IntCritter', 'Metadata/Effects/PlayerEffects/IntEffect', 'Metadata/Effects/Spells/maneuver_mechanics/AfterImage/IntAfterImage', 3984, 3963, 3991, 6708, 0, 0, 'Art/2DArt/UIImages/InGame/Classes/Int/PassiveSkillScreenStartNodeBackground', 3956, 3609, 8413, 3616, 2794, 'Int', 'int', 'int_back', 558, 70, 3970, 3977, 3, 100, 10477, 3631),
(2, 'Metadata/Characters/StrDexInt/StrDexInt', 'Scion', 'Metadata/Characters/StrDexInt/StrDexInt.ao', 'Metadata/Characters/StrDexInt/StrDexInt.act', 38, 34, 833, 2, 6, 8, '', 0, 20, 20, 20, '[4474]', 'A Scion is perfection in mind, body, and grace. The crowning glory of our civilization, offering us hope, offering us light.' || char(13) || '
 ' || char(13) || '
But you gave us only murder and darkness.' || char(13) || '
 ' || char(13) || '
May Wraeclast embrace you as we cannot, for your very presence has become too painful to bear.', 209, 0, 6, 1, 2, 'Audio/Dialogue/NPC/DominusGlyph/Dom_Intro_Scion.ogg', '[502]', 'F', 'Traits: Strength, Dexterity, Intelligence', 734, NULL, NULL, NULL, 5, '[]', '', 0, 0, 'http://down.qq.com/poe/videos/class/ClassStrDexInt.bk2', 'StrDexInt', 'Metadata/Characters/StrDexInt/StrDexIntLoginSceneFallOfOriath.ao', 'Metadata/Critters/PlayerCritters/StrDexIntCritter', 'Metadata/Effects/PlayerEffects/StrDexIntEffect', 'Metadata/Effects/Spells/maneuver_mechanics/AfterImage/StrDexIntAfterImage', 3988, 3967, 3995, 6712, 0, 0, 'Art/2DArt/UIImages/InGame/Classes/StrDexInt/PassiveSkillScreenStartNodeBackground', 3960, 3613, 8417, 3620, 2789, 'StrDexInt', 'strdexint', 'strdexint_back', 562, 80, 3974, 3981, 7, 100, 10481, 3635),
(3, 'Metadata/Characters/Dex/Dex', 'Ranger', 'Metadata/Characters/Dex/Dex.ao', 'Metadata/Characters/Dex/Dex.act', 38, 34, 833, 2, 5, 8, '', 2, 14, 32, 14, '[4474]', 'Swift and silent you stole the bounty of others. ' || char(13) || '
 ' || char(13) || '
A crow that plunders our crops. A stray dog that slaughters our sheep. ' || char(13) || '
 ' || char(13) || '
Oriath is a land of men, not animals. Think on that, Ranger, when Wraeclast shows you how to truly live like an animal.', 139, 0, 6, 1, 2, 'Audio/Dialogue/NPC/DominusGlyph/Dom_Intro_Ranger.ogg', '[612]', 'F', 'Traits: Dexterity, Ranged', 341, 44, 341, 612, 2, '[1231,2833]', 'Art/2DArt/BaseClassIllustrations/Dex.dds', -850, -1255, 'http://down.qq.com/poe/videos/class/ClassDex.bk2', 'Dex', 'Metadata/Characters/Dex/DexLoginSceneFallOfOriath.ao', 'Metadata/Critters/PlayerCritters/DexCritter', 'Metadata/Effects/PlayerEffects/DexEffect', 'Metadata/Effects/Spells/maneuver_mechanics/AfterImage/DexAfterImage', 3983, 3962, 3990, 6707, -536, -281.9200134277344, 'Art/2DArt/UIImages/InGame/Classes/Dex/PassiveSkillScreenStartNodeBackground', 3955, 3608, 8412, 3615, 2795, 'Dex', 'dex', 'dex_back', 557, 80, 3969, 3976, 2, 100, 10476, 3630),
(4, 'Metadata/Characters/StrDex/StrDex', 'Duelist', 'Metadata/Characters/StrDex/StrDex.ao', 'Metadata/Characters/StrDex/StrDex.act', 38, 34, 833, 2, 6, 8, '', 4, 23, 23, 14, '[4474]', 'You were born to be swift and strong. What did you do with your gifts, Duelist? You squandered them on self-indulgence.' || char(13) || '
 ' || char(13) || '
Sin has led you here, your path inked in the blood of gratuitous murder.' || char(13) || '
 ' || char(13) || '
You have betrayed the Grand Arena. Now Wraeclast shall be your audience... and your foe.', 18, 0, 6, 1, 2, 'Audio/Dialogue/NPC/DominusGlyph/Dom_Intro_Duelist.ogg', '[502]', 'M', 'Traits: Strength, Dexterity', 329, 18, 329, 502, 1, '[1231]', 'Art/2DArt/BaseClassIllustrations/StrDex.dds', -1959, -1432, 'http://down.qq.com/poe/videos/class/ClassStrDex.bk2', 'StrDex', 'Metadata/Characters/StrDex/StrDexLoginSceneFallOfOriath.ao', 'Metadata/Critters/PlayerCritters/StrDexCritter', 'Metadata/Effects/PlayerEffects/StrDexEffect', 'Metadata/Effects/Spells/maneuver_mechanics/AfterImage/StrDexAfterImage', 3985, 3964, 3992, 6709, 0, -699.2000122070312, 'Art/2DArt/UIImages/InGame/Classes/StrDex/PassiveSkillScreenStartNodeBackground', 3957, 3610, 8414, 3617, 2791, 'StrDex', 'strdex', 'strdex_back', 559, 90, 3971, 3978, 4, 100, 10478, 3632),
(5, 'Metadata/Characters/DexInt/DexInt', 'Shadow', 'Metadata/Characters/DexInt/DexInt.ao', 'Metadata/Characters/DexInt/DexInt.act', 38, 34, 833, 2, 5, 8, '', 6, 14, 23, 23, '[4474]', 'You were born with quickness of body and sharpness of mind. How have you paid for these gifts? With innocent blood.' || char(13) || '
 ' || char(13) || '
Yours is a predatory profession. The business of butchery. You have stolen many a life to fill your purse.' || char(13) || '
 ' || char(13) || '
Now you will earn your redemption in Wraeclast.', 80, 0, 6, 1, 2, 'Audio/Dialogue/NPC/DominusGlyph/Dom_Intro_Shadow.ogg', '[413]', 'M', 'Traits: Dexterity, Intelligence', 330, 306, 342, 384, 3, '[2452]', 'Art/2DArt/BaseClassIllustrations/DexInt.dds', -1140, -2172, 'http://down.qq.com/poe/videos/class/ClassDexInt.bk2', 'DexInt', 'Metadata/Characters/DexInt/DexIntLoginSceneFallOfOriath.ao', 'Metadata/Critters/PlayerCritters/DexIntCritter', 'Metadata/Effects/PlayerEffects/DexIntEffect', 'Metadata/Effects/Spells/maneuver_mechanics/AfterImage/DexIntAfterImage', 3987, 3966, 3994, 6711, 0, -291.3999938964844, 'Art/2DArt/UIImages/InGame/Classes/DexInt/PassiveSkillScreenStartNodeBackground', 3959, 3612, 8416, 3619, 2793, 'DexInt', 'dexint', 'dexint_back', 561, 80, 3973, 3980, 6, 100, 10480, 3634),
(6, 'Metadata/Characters/StrInt/StrInt', 'Templar', 'Metadata/Characters/StrInt/StrInt.ao', 'Metadata/Characters/StrInt/StrInt.act', 38, 34, 833, 2, 6, 8, '', 5, 23, 14, 23, '[4474]', 'You swore, sinew and soul, to serve God and the Order of the Templar. For years you built a life upon Faith, only to smite it asunder with one sinful blow. ' || char(13) || '
 ' || char(13) || '
And is that not the greatest folly of all? To lose Faith when it''s all you have left?' || char(13) || '
 ' || char(13) || '
You were once the chosen of God. A Templar. You are now the chosen of Wraeclast. An exile.', 743, 0, 6, 1, 2, 'Audio/Dialogue/NPC/DominusGlyph/Dom_Intro_Templar.ogg', '[584]', 'M', 'Traits: Strength, Intelligence', 841, 384, 141, 584, 1, '[4536]', 'Art/2DArt/BaseClassIllustrations/StrInt.dds', -918, -1581, 'http://down.qq.com/poe/videos/class/ClassStrInt.bk2', 'StrInt', 'Metadata/Characters/StrInt/StrIntLoginSceneFallOfOriath.ao', 'Metadata/Critters/PlayerCritters/StrIntCritter', 'Metadata/Effects/PlayerEffects/StrIntEffect', 'Metadata/Effects/Spells/maneuver_mechanics/AfterImage/StrIntAfterImage', 3986, 3965, 3993, 6710, 717, 182.39999389648438, 'Art/2DArt/UIImages/InGame/Classes/StrInt/PassiveSkillScreenStartNodeBackground', 3958, 3611, 8415, 3618, 2790, 'StrInt', 'strint', 'strint_back', 560, 80, 3972, 3979, 5, 100, 10479, 3633);
